    if(os.sp.pf111inc){const rt=os.sp.pf111tax/os.sp.pf111inc*100;const snap=[1,4,5,9,10,12.5,15,20,25,30,50,60].reduce((a,b)=>Math.abs(b-rt)<Math.abs(a-rt)?b:a,10);add("1",os.sp.pf111inc,snap);}
