      let neg=rs.filter(r=>r.inc<0).reduce((a,r)=>a+r.inc,0);rs.forEach(r=>{if(r.inc<0)r.inc=0;});
      const pos=rs.filter(r=>r.inc>0);const psum=pos.reduce((a,r)=>a+r.inc,0);
